-- Fix channels primary key and normalize web-created panel provisioning
SET @db:=DATABASE();
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='channels' AND COLUMN_NAME='id')=0,'ALTER TABLE channels ADD COLUMN id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY FIRST','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q:=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='marzban_panel' AND COLUMN_NAME='provisioning_status')=0,'ALTER TABLE marzban_panel ADD COLUMN provisioning_status VARCHAR(20) NOT NULL DEFAULT ''incomplete'',ADD COLUMN provisioning_error VARCHAR(1000) NULL,ADD COLUMN reference_username VARCHAR(191) NULL','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
UPDATE marzban_panel SET version_panel='1',type='marzban' WHERE type='pasargard';
UPDATE marzban_panel SET sublink=COALESCE(NULLIF(sublink,''),'onsublink'),config=COALESCE(NULLIF(config,''),'offconfig'),MethodUsername=COALESCE(NULLIF(MethodUsername,''),'آیدی عددی + حروف و عدد رندوم'),TestAccount=COALESCE(NULLIF(TestAccount,''),'ONTestAccount'),limit_panel=COALESCE(NULLIF(limit_panel,''),'unlimited'),namecustom=COALESCE(NULLIF(namecustom,''),'none'),Methodextend=COALESCE(NULLIF(Methodextend,''),'ریست حجم و زمان'),conecton=COALESCE(NULLIF(conecton,''),'offconecton'),inboundid=COALESCE(NULLIF(inboundid,''),'1'),inboundstatus=COALESCE(NULLIF(inboundstatus,''),'offinbounddisable'),linksubx=COALESCE(NULLIF(linksubx,''),url_panel),status_extend=COALESCE(NULLIF(status_extend,''),'on_extend'),subvip=COALESCE(NULLIF(subvip,''),'offsubvip'),changeloc=COALESCE(NULLIF(changeloc,''),'offchangeloc'),on_hold_test=COALESCE(NULLIF(on_hold_test,''),'1');
UPDATE marzban_panel SET provisioning_status=CASE WHEN (type='marzban' AND (inbounds IS NULL OR inbounds='' OR proxies IS NULL OR proxies='')) OR (type='marzneshin' AND (proxies IS NULL OR proxies='')) THEN 'incomplete' ELSE 'ready' END,provisioning_error=CASE WHEN (type='marzban' AND (inbounds IS NULL OR inbounds='' OR proxies IS NULL OR proxies='')) OR (type='marzneshin' AND (proxies IS NULL OR proxies='')) THEN 'Reference user synchronization required' ELSE NULL END;
